import itertools
from pysat.solvers import Glucose3

def check_ramsey(n, r, b):
    edges = list(itertools.combinations(range(n), 2))
    solver = Glucose3()
    var_map = {e: i+1 for i, e in enumerate(edges)}

    # No red K_r (color 0)
    for c in itertools.combinations(range(n), r):
        clause = [var_map[e] for e in itertools.combinations(c, 2)]
        solver.add_clause(clause)

    # No blue K_b (color 1)
    for c in itertools.combinations(range(n), b):
        clause = [-var_map[e] for e in itertools.combinations(c, 2)]
        solver.add_clause(clause)

    return solver.solve()

for n in range(6, 14):
    print(f"n={n}: {check_ramsey(n, 4, 3)}")
